  ('sq1', 'eo', 'https://speedcubedb.com/a/sq1/SQ1EO; https://cubingapp.com/algorithms/SQ1-EO; https://github.com/spencerchubb/cubingapp/commit/613a49885dc618023368e5f0c2a25024b8c7e9a5', NOW()),
  ('sq1', 'ep', 'https://speedcubedb.com/a/sq1/SQ1EP; https://cubingapp.com/algorithms/SQ1-EP; https://github.com/spencerchubb/cubingapp/commit/613a49885dc618023368e5f0c2a25024b8c7e9a5', NOW()),
  ('sq1', 'obl', 'https://cubingapp.com/algorithms/SQ1-OBL; https://github.com/spencerchubb/cubingapp/commit/613a49885dc618023368e5f0c2a25024b8c7e9a5', NOW())
