          "source": "cubingapp"
        }
      ]
    ]
  },
  {
    "sourceName": "Solved / Adj",
    "targetName": "Solved / Adj",
    "position": 6,
    "subgroup": "Top Solved",
    "algs": [
      [
        {
          "alg": "/ 3,-3 / 0,3 / -3,0 / 3,0 / -3,0 / ",
          "source": "cubingapp"
        }
      ]
    ]
  },
